    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    seen, comps = set(), []
    for p in pts:
        if p in seen:
            continue
        stack, comp = [p], []
        seen.add(p)
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
